// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    // fuzzed params: amount to send, and an address that will be the caller (actor)
    function testFuzz_property(uint256 amount, address actor) public {
        // keep amount in a practical range so transfer can attempt to send
        amount = bound(amount, 0, 1 ether);

        // Deploy a helper that will revert when receiving funds
        Reverter rev = new Reverter();

        // Fund the contract so transfer has balance to attempt sending
        vm.deal(address(c), 1 ether);

        // Make actor be the owner by deploying a fresh C where owner is msg.sender in constructor.
        // But the test must use the c deployed in setUp(); owner there is the test contract address.
        // So to call as owner, we must prank as the test contract (this) because constructor set owner = msg.sender (the test via new C())
        // In setUp(), c was deployed by this test contract, so owner == address(this).

        // Ensure actor is treated adversarially: we will call sendTo as the owner (this contract) so it reaches the transfer.
        // Now call c.sendTo with receiver = address(rev) and amount.

        bool ok;
        try c.sendTo(address(rev), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: when the recipient reverts on receiving Ether, the correct contract (which performs transfer)
        // will revert for at least some amounts > 0 (transfer propagates the revert). The mutant that removed transfer
        // will not revert. Therefore, for OUR scenario with a reverting recipient and caller == owner, the call
        // MUST revert (ok == false) whenever amount > 0 and c has sufficient balance. We encoded amount bounded up to 1 ether
        // and funded c with 1 ether, so for any amount in (0, balance] the reference will revert; the mutant will not.

        if (amount > 0 && amount <= address(c).balance) {
            assertTrue(!ok);
        } else {
            // when amount == 0 or amount > balance, behavior may differ (no transfer or insufficient funds leading to revert),
            // but we only assert the decisive domain above. To keep the property universal over tested domain, we accept any outcome here.
            assertTrue(true);
        }
    }
}

// Helper that reverts when receiving Ether
contract Reverter {
    receive() external payable {
        revert("reverting receiver");
    }
}
